(92501, 3586, 1175, '<td valign="top">Great texture shot.</td>', 'Great texture shot.', '2002-07-22 15:04:00.000000', NULL, 1),
(92502, 3586, 641, '<td valign="top">Nice detail and color. Dof is a little distracting though.</td>', 'Nice detail and color. Dof is a little distracting though.', '2002-07-22 16:29:00.000000', NULL, 1),
