(92769, 3606, 2777, '<td valign="top">Blurred</td>', 'Blurred', '2002-07-23 07:25:00.000000', NULL, 1),
(92770, 3606, 2337, '<td valign="top">I know that soft focus may be a matter of choice, but when you want to show texture, it just doesn''t work.  Soft focus hides texture, it doesn''t bring it to the forefront.  But that''s just me :)</td>', 'I know that soft focus may be a matter of choice, but when you want to show texture, it just doesn''t work.  Soft focus hides texture, it doesn''t bring it to the forefront.  But that''s just me :)', '2002-07-23 10:22:00.000000', NULL, 1),
