(94250, 3702, 668, '<td valign="top">maybe amongst the twigs or grass would enahnce the effect</td>', 'maybe amongst the twigs or grass would enahnce the effect', '2002-07-22 07:52:00.000000', NULL, 1),
(94251, 3702, 1569, '<td valign="top">Could use a bit more contrast--just a touch.</td>', 'Could use a bit more contrast--just a touch.', '2002-07-22 10:05:00.000000', NULL, 1),
