INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(94253, 3702, 641, '<td valign="top">Nice mix of textures and I like the tones used. Good job.</td>', 'Nice mix of textures and I like the tones used. Good job.', '2002-07-22 16:57:00.000000', NULL, 1),
(94254, 3702, 2553, '<td valign="top">Very nice photo, I like the different types of texture and the lighting.  My favorite thing about it is that it is not just a bunch of textures thrown together - they look like they belong together.</td>', 'Very nice photo, I like the different types of texture and the lighting.  My favorite thing about it is that it is not just a bunch of textures thrown together - they look like they belong together.', '2002-07-22 17:58:00.000000', NULL, 1),
(94255, 3702, 2275, '<td valign="top">i like the way the nest and the item its sitting on match colors.</td>', 'i like the way the nest and the item its sitting on match colors.', '2002-07-23 01:53:00.000000', NULL, 1),
(94256, 3702, 1280, '<td valign="top">I love the contrast of textures here.  Nice coloring too!</td>', 'I love the contrast of textures here.  Nice coloring too!', '2002-07-23 18:14:00.000000', NULL, 1),
(94257, 3702, 1564, '<td valign="top">This picture would be better if it had a completly white backround.  It blends in too much with the brown backround.</td>', 'This picture would be better if it had a completly white backround.  It blends in too much with the brown backround.', '2002-07-24 14:08:00.000000', NULL, 1),
