INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(95453, 3774, 2553, '<td valign="top">Good response to the challenge, with nice mood and composition.</td>', 'Good response to the challenge, with nice mood and composition.', '2002-07-22 09:37:00.000000', NULL, 1),
(95454, 3774, 2295, '<td valign="top">Were you trying for the effect on the finger?  If so, good job.  If not, Hmmmm...  Good picture.  Nice focus and lighting.</td>', 'Were you trying for the effect on the finger?  If so, good job.  If not, Hmmmm...  Good picture.  Nice focus and lighting.', '2002-07-22 09:45:00.000000', NULL, 1),
(95455, 3774, 2780, '<td valign="top">would be better i feel if the finger wasnt blurred.</td>', 'would be better i feel if the finger wasnt blurred.', '2002-07-22 13:44:00.000000', NULL, 1),
(95456, 3774, 2634, '<td valign="top">I thought of this idea right after the contest ended - original one!</td>', 'I thought of this idea right after the contest ended - original one!', '2002-07-22 14:17:00.000000', NULL, 1),
(95457, 3774, 1054, '<td valign="top">Excellent interpretation, superb execution. My only complaint is that the combination of the moving finger and long exposure create a ghosted effect (it looks like you can see the braille through the finger) 9-ClubJuggle</td>', 'Excellent interpretation, superb execution. My only complaint is that the combination of the moving finger and long exposure create a ghosted effect (it looks like you can see the braille through the finger) 9-ClubJuggle', '2002-07-22 15:00:00.000000', NULL, 1),
(95458, 3774, 1175, '<td valign="top">Great idea.</td>', 'Great idea.', '2002-07-22 15:02:00.000000', NULL, 1),
(95459, 3774, 2223, '<td valign="top">i like how the tip of the finger is see through..neat!</td>', 'i like how the tip of the finger is see through..neat!', '2002-07-22 15:19:00.000000', NULL, 1),
(95460, 3774, 878, '<td valign="top">Interesting shot, I like the motion blur on this.</td>', 'Interesting shot, I like the motion blur on this.', '2002-07-22 15:47:00.000000', NULL, 1),
